((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"year":2002,"id":"2002-7-8","grades":[7,8],"label":"7–8 классы","tasksUrl":"assets/kenguru/kenguru_2002_class_7-8.pdf","answersUrl":"assets/kenguru/kenguru_2002_answers.pdf","solutionUrl":null,"answerLetters":"ABCDE","cards":[{"number":1,"title":"Таинственное число","question":"Число, равное сумме цифр своего куба, назовем таинственным. Какое из следующих чисел таинственное?","options":[{"text":"9999"},{"text":"10"},{"text":"9"},{"text":"8"},{"text":"2"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Куб числа 8 равен 512."},{"title":"Ответ","text":"Складываем цифры: 5 + 1 + 2 = 8. Это исходное число."}]},{"number":2,"title":"Дорожка стадиона","question":"Дорожка вокруг стадиона разделена флажками на участки одинаковой длины. Джек бегает в 3 раза быстрее своей младшей сестры Сюзан. Они стартуют одновременно из точки P, но в противоположных направлениях. В какой точке они встретятся?","options":[{"text":"A"},{"text":"B"},{"text":"C"},{"text":"D"},{"text":"E"}],"condition":{"src":"assets/grades-7-8/2002/task-02.png","width":178,"height":119,"alt":"Стадион с общей точкой старта P внизу. Джек бежит налево, Сюзан направо. На дорожке отмечены равные участки, а точки A, B, C, D и E идут от левого края стадиона через верх к правому краю."},"answer":4,"points":3,"review":[{"title":"Решение","text":"До встречи они вместе пробегут весь круг: Джек преодолеет три части пути, а Сюзан — одну такую же часть."},{"title":"Ответ","text":"Сюзан бежит от P направо. Четверть круга в этом направлении приводит к точке E."}]},{"number":3,"title":"Коробки со сливами","question":"Коробка яблок сто́ит 2 евро, коробка груш — 3 евро, а коробка слив — 4 евро. Имеется 8 коробок с фруктами общей стоимостью 23 евро. Сколько из них, самое большее, содержат сливы?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Восемь коробок яблок стоили бы 16 евро. Каждая замена яблок сливами увеличивает стоимость на 2 евро. Четыре такие замены дали бы уже 24 евро."},{"title":"Ответ","text":"Три коробки слив, одна коробка груш и четыре коробки яблок стоят 12 + 3 + 8 = 23 евро. Значит, максимум — три коробки слив."}]},{"number":4,"title":"Поворот кубика","question":"На нижней грани кубика нарисованы 6 точек, на левой — 4 и на задней — 2. Какое наибольшее количество точек можно увидеть одновременно, поворачивая этот кубик в руках?","options":[{"text":"15"},{"text":"14"},{"text":"13"},{"text":"12"},{"text":"другой ответ"}],"condition":{"src":"assets/grades-7-8/2002/task-04.png","width":97,"height":82,"alt":"Кубик: на видимой верхней грани три точки, на передней одна, на правой пять."},"answer":2,"points":3,"review":[{"title":"Решение","text":"По рисунку противоположные грани образуют пары 6 и 3, 4 и 5, 2 и 1. Из каждой пары можно видеть не более одной грани."},{"title":"Ответ","text":"Грани с 6, 5 и 2 точками попарно соседние и сходятся в одной вершине. На них 6 + 5 + 2 = 13 точек."}]},{"number":5,"title":"Квадрат суммы","question":"Разность между квадратом суммы и суммой квадратов различных натуральных чисел может равняться","options":[{"text":"2"},{"text":"9"},{"text":"0"},{"text":"−4"},{"text":"8"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"При раскрытии квадрата суммы квадраты слагаемых сокращаются. Остаётся удвоенная сумма попарных произведений."},{"title":"Ответ","text":"Для двух разных натуральных чисел 1 и 4 получаем 2 · 1 · 4 = 8."}]},{"number":6,"title":"Флаг на ветру","question":"Таня видит из окна флаг, который развевается на ветру. Флаг имеет форму прямоугольника. Какую из картинок Таня не могла увидеть?","options":[{"text":"","image":"assets/grades-7-8/2002/task-06-answer-1.svg","description":"Слева вверху ступенька, справа нижняя кромка идёт вверх по диагонали."},{"text":"","image":"assets/grades-7-8/2002/task-06-answer-2.svg","description":"Полотно отходит от древка на середине высоты, дальше снизу виден угловой вырез."},{"text":"","image":"assets/grades-7-8/2002/task-06-answer-3.svg","description":"Верхняя и нижняя кромки горизонтальны, свободный край вертикален."},{"text":"","image":"assets/grades-7-8/2002/task-06-answer-4.svg","description":"Верхняя кромка поднимается углом, нижняя наклонена вверх от древка."},{"text":"","image":"assets/grades-7-8/2002/task-06-answer-5.svg","description":"Верхняя кромка горизонтальна, внизу свободный край скошен."}],"condition":{"src":"assets/grades-7-8/2002/task-06.svg","width":76,"height":63,"alt":"Прямоугольный флаг прикреплён левой стороной к вертикальному древку."},"answer":1,"points":3,"review":[{"title":"Решение","text":"Та сторона прямоугольного флага, которая прикреплена к древку, остаётся вдоль него и сохраняет свою длину."},{"title":"Ответ","text":"На рисунке B полотно отходит от древка посередине закреплённой стороны. Сгибы свободной части флага не могут укоротить закреплённую сторону."}]},{"number":7,"title":"Остаток при делении","question":"Среди чисел 1, 2, …, 100 больше всего чисел, дающих при делении на 11 остаток","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"другой ответ"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Решение","text":"В каждом из девяти последовательных блоков по 11 чисел от 1 до 99 все остатки встречаются по одному разу."},{"title":"Ответ","text":"Число 100 даёт при делении на 11 остаток 1. Только этот остаток встречается десять раз."}]},{"number":8,"title":"Дни недели","question":"Если бы вчера был понедельник, то через 72 часа после сегодняшнего полудня был бы день недели, который на самом деле будет послезавтра. Из этого следует, что завтра будет","options":[{"text":"понедельник"},{"text":"вторник"},{"text":"четверг"},{"text":"воскресенье"},{"text":"другой день"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Если бы вчера был понедельник, сегодня был бы вторник. Через 72 часа, то есть трое суток, была бы пятница."},{"title":"Ответ","text":"Значит, на самом деле послезавтра будет пятница, а завтра — четверг."}]},{"number":9,"title":"Нули в произведении","question":"Любитель арифметики перемножил первые 2002 простых числа. На сколько нулей оканчивается произведение?","options":[{"text":"0"},{"text":"1"},{"text":"10"},{"text":"20"},{"text":"100"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Каждый нуль в конце произведения соответствует одному множителю 10 = 2 · 5."},{"title":"Ответ","text":"Среди простых чисел только 2 делится на 2 и только 5 делится на 5. Пара этих множителей одна, поэтому в конце один нуль."}]},{"number":10,"title":"Генеалогическое дерево","question":"Ваня рассматривает свое генеалогическое дерево, где отмечены одни мужчины. Стрелка идет от отца к сыну. Как звали сына брата деда брата отца Вани?","options":[{"text":"Жан"},{"text":"Вано"},{"text":"Джон"},{"text":"Иоганн"},{"text":"другой ответ"}],"condition":{"src":"assets/grades-7-8/2002/task-10.svg","width":196,"height":159,"alt":"От Ивана идут стрелки к Йовану и Джону. Йован ведёт к Иоганну, Джон к Жану и Яну, Ян к Вано, Жан к Джованни и Ованесу, Ованес к Ване."},"answer":3,"points":3,"review":[{"title":"Решение","text":"Отец Вани — Ованес. Брат Ованеса — Джованни. Отец Джованни — Жан, а его дед — Джон."},{"title":"Ответ","text":"У Джона есть брат Йован. Сын Йована — Иоганн."}]},{"number":11,"title":"Пять дробей","question":"Какая из следующих дробей самая большая?","options":[{"text":"7/8"},{"text":"66/77"},{"text":"555/666"},{"text":"4444/5555"},{"text":"33333/44444"}],"condition":null,"answer":0,"points":4,"review":[{"title":"Решение","text":"Во второй дроби сокращаем на 11, в третьей — на 111, в четвёртой — на 1111, в пятой — на 11111."},{"title":"Ответ","text":"Получаем 7/8, 6/7, 5/6, 4/5, 3/4. До единицы первой дроби не хватает 1/8, а у остальных недостающие доли больше. Значит, первая дробь самая большая."}]},{"number":12,"title":"Две окружности","question":"Точки P и Q — центры двух касающихся окружностей. Прямоугольник ABCD касается бо́льшей окружности в точках T и B, а меньшей — в точке A. Его площадь равна 15. Найдите площадь треугольника PQT.","options":[{"text":"4"},{"text":"15/4"},{"text":"π/2"},{"text":"5"},{"text":"3"}],"condition":{"src":"assets/grades-7-8/2002/task-12.svg","width":147,"height":89,"alt":"Окружности с центрами P и Q касаются на стороне AB прямоугольника ABCD. A и B — крайние точки касания, T на стороне CD под центром Q. Треугольник PQT закрашен."},"answer":1,"points":4,"review":[{"title":"Решение","text":"Если радиусы окружностей равны r и R, то PQ = r + R, а AB = r + PQ + R = 2PQ. Высота прямоугольника AD равна QT = R."},{"title":"Ответ","text":"Площадь треугольника PQT равна PQ · QT / 2, то есть четверти площади прямоугольника: 15/4."}]},{"number":13,"title":"Отношения разностей","question":"Если a : b = 9 : 4 и b : c = 5 : 3, то (a − b) : (b − c) равно","options":[{"text":"7 : 12"},{"text":"25 : 8"},{"text":"4 : 1"},{"text":"5 : 2"},{"text":"невозможно определить"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Возьмём общую меру для b: в обоих отношениях пусть b = 20k. Тогда a = 45k и c = 12k."},{"title":"Ответ","text":"Разности равны 25k и 8k. Их отношение равно 25 : 8."}]},{"number":14,"title":"Запасы воды","question":"После того, как на борт были подняты 30 потерпевших кораблекрушение, оказалось, что запасов питьевой воды, имеющейся на корабле, хватит только на 50 дней, а не на 60, как раньше. Сколько людей было на корабле сначала?","options":[{"text":"15"},{"text":"40"},{"text":"110"},{"text":"140"},{"text":"150"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Пусть сначала на корабле было x человек. Запас воды рассчитан на 60x человеко-дней, а после спасения людей — на 50(x + 30) человеко-дней."},{"title":"Ответ","text":"Приравниваем: 60x = 50x + 1500. Получаем x = 150."}]},{"number":15,"title":"Монеты в клетках","question":"В некоторых клетках прямоугольника 2 × 9 лежит по монете. Монеты расположены так, что если в какой-то клетке нет монеты, то хотя бы в одной из соседних клеток монета есть (соседними считаются клетки с общей стороной). Тогда наименьшее возможное число монет равно","options":[{"text":"4"},{"text":"5"},{"text":"6"},{"text":"8"},{"text":"9"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Одна монета покрывает свою клетку и не более трёх соседних. Четыре монеты покроют не более 16 клеток из 18."},{"title":"Ответ","text":"Пять монет можно положить в столбцах 1, 3, 5, 7 и 9, чередуя верхний и нижний ряды. В нечётных столбцах покрыты обе клетки, в чётных каждая клетка покрыта соседней монетой в своём ряду."}]},{"number":16,"title":"Вес четырёх кошек","question":"Четырех кошек взвесили попарно во всех возможных комбинациях. Получились веса: 7 кг, 8 кг, 9 кг, 10 кг, 11 кг и 12 кг. Тогда общий вес всех четырех кошек равен","options":[{"text":"16 кг"},{"text":"18 кг"},{"text":"19 кг"},{"text":"57 кг"},{"text":"невозможно определить"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Вес каждой кошки вошёл в три из шести взвешиваний — с каждой другой кошкой по одному разу."},{"title":"Ответ","text":"Сумма шести результатов равна 57 кг. Общий вес кошек в три раза меньше: 19 кг."}]},{"number":17,"title":"После числа 1861","question":"Дано число 1861. Сколько следующих за ним подряд чисел не делятся ни на 12, ни на 15?","options":[{"text":"2"},{"text":"5"},{"text":"10"},{"text":"13"},{"text":"другой ответ"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Ближайшее кратное 12 после 1861 — это 1872, а ближайшее кратное 15 — это 1875."},{"title":"Ответ","text":"Первое число, на котором последовательность прерывается, — 1872. От 1862 до 1871 включительно десять чисел."}]},{"number":18,"title":"Расколотый циферблат","question":"Циферблат часов раскололся на 3 части. При этом ни одна линия разлома не прошла через числа на циферблате, а суммы чисел в каждой из частей оказались одинаковыми. Тогда обязательно","options":[{"text":"12 и 3 — в разных частях"},{"text":"8 и 4 — в одной и той же части"},{"text":"7 и 5 — в разных частях"},{"text":"11, 1 и 5 — в одной и той же части"},{"text":"2, 11 и 9 — в одной и той же части"}],"condition":{"src":"assets/grades-7-8/2002/task-18.svg","width":128,"height":128,"alt":"Круглый циферблат с числами от 1 до 12. Линии разлома не нанесены."},"answer":0,"points":4,"review":[{"title":"Решение","text":"Сумма всех чисел от 1 до 12 равна 78, так что на каждую часть приходится 26."},{"title":"Решение","text":"Две части не могут чередоваться по окружности: соединяющие их участки внутри циферблата пересеклись бы. Поэтому по крайней мере две из трёх частей занимают непрерывные ряды на окружности."},{"title":"Ответ","text":"Проверяем суммы подряд идущих чисел по кругу. Сумму 26 дают только ряды 5, 6, 7, 8 и 11, 12, 1, 2. Значит, 12 попадает во второй ряд, а 3 остаётся в третьей части."}]},{"number":19,"title":"Числа из двух слов","question":"Жан-Кристоф продолжает изучать русский язык. Он выписывает цифрами и русскими словами все такие натуральные числа, бо́льшие 100, что их словесная запись состоит из двух слов, а в цифровой записи каждая следующая цифра (слева направо) не меньше предыдущей. Сколько таких чисел?","options":[{"text":"0"},{"text":"9"},{"text":"18"},{"text":"бесконечно много"},{"text":"другой ответ"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Нулей в записи быть не может: первая цифра положительна, а дальше цифры не убывают. Любое число от 1000 без нулей требует слов для старших разрядов, сотен и остатка, то есть больше двух слов."},{"title":"Ответ","text":"У трёхзначного числа после слова для сотен требуется ещё ровно одно слово. Ненулевые десятки и единицы выражаются одним словом только у чисел от 11 до 19. Первая цифра при этом может быть только 1, так что подходят девять чисел от 111 до 119."}]},{"number":20,"title":"Выборы мэра","question":"В Цветочном городе выбирают мэра. Знайка набрал 51% голосов, а Незнайка — 49%. При этом сами кандидаты не участвовали в голосовании. Если бы каждый из них проголосовал за себя, то Незнайка получил бы","options":[{"text":"49% голосов"},{"text":"50% голосов"},{"text":"более 50% голосов"},{"text":"менее 49% голосов"},{"text":"более 49%, но менее 50% голосов"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Два новых голоса разделились бы поровну. Незнайка получил бы половину новых голосов, поэтому его доля выросла бы с 49%."},{"title":"Ответ","text":"У обоих кандидатов стало бы на один голос больше. Знайка по-прежнему опережал бы Незнайку, поэтому доля Незнайки осталась бы меньше 50%."}]},{"number":21,"title":"Наименьшая сумма","question":"Если a + 2b ≥ 3, b + 3c ≥ 5, a, b, c ≥ 0, то наименьшее из возможных значений суммы a + b + c равно","options":[{"text":"2"},{"text":"5/3"},{"text":"8/3"},{"text":"3"},{"text":"5"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Складываем неравенства и делим на 3: a/3 + b + c ≥ 8/3. Поскольку a ≥ 0, имеем a + b + c ≥ 8/3."},{"title":"Ответ","text":"При a = 0, b = 3/2, c = 7/6 оба исходных неравенства обращаются в равенства. Сумма равна 8/3."}]},{"number":22,"title":"Пересечение треугольников","question":"Два равных треугольника ABC и DEC расположены так, как показано на рисунке. Известно, что DC = AC = 1, CB = CE = 4, S(ABC) = 1. Найдите площадь заштрихованной фигуры.","options":[{"text":"1/2"},{"text":"1/4"},{"text":"1/5"},{"text":"2/5"},{"text":"2/3"}],"condition":{"src":"assets/grades-7-8/2002/task-22.svg","width":182,"height":126,"alt":"Треугольники ABC и DEC. На прямой BC лежит D, на прямой EC лежит A, а BA и DE пересекаются в F. Заштрихован четырёхугольник CDFA."},"answer":3,"points":5,"review":[{"title":"Решение","text":"За единичные направления возьмём отрезки CD и CA. В этих координатах B = (4, 0), E = (0, 4), а прямые BA и DE имеют уравнения x + 4y = 4 и 4x + y = 4."},{"title":"Решение","text":"В точке пересечения F получаем x = y = 4/5. Площадь CDA составляет четверть площади ABC, то есть 1/4."},{"title":"Ответ","text":"Треугольники CDF и CAF имеют высоты по 4/5 соответствующих высот треугольника CDA. Сумма их площадей равна 2 · (4/5) · (1/4) = 2/5."}]},{"number":23,"title":"Перелёт мухи","question":"Муха вылетает из Бухареста в Париж (2500 км) со скоростью 1 м/сек. Она удваивает скорость после каждого метра пути. Оцените время полета мухи.","options":[{"text":"около 10 лет"},{"text":"около 2 лет"},{"text":"около 3 месяцев"},{"text":"около суток"},{"text":"менее 2 секунд"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"На первый метр ушла 1 секунда, на второй — 1/2 секунды, на третий — 1/4 секунды, и так далее."},{"title":"Ответ","text":"Сумма после k метров равна 2 − 1/(2^(k − 1)) секунды: оставшаяся до двух секунд разность на каждом метре делится пополам. Любое конечное расстояние муха пролетит менее чем за две секунды."}]},{"number":24,"title":"Порядок квадратов","question":"Какое из следующих двойных неравенств невозможно, если x₁ < x₂ < x₃?","options":[{"text":"x₁² < x₂² < x₃²"},{"text":"x₂² < x₃² < x₁²"},{"text":"x₂² < x₁² < x₃²"},{"text":"x₁² < x₃² < x₂²"},{"text":"x₃² < x₂² < x₁²"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Если x₂ ≥ 0, то x₃ дальше от нуля, чем x₂. Если x₂ < 0, то x₁ дальше от нуля, чем x₂."},{"title":"Ответ","text":"В обоих случаях квадрат среднего числа не может быть самым большим. Это исключает вариант D."}]},{"number":25,"title":"Три шага с треугольником","question":"За один шаг разрешается либо сдвинуть треугольник на единицу вверх, либо зеркально отразить относительно оси OX, либо зеркально отразить относительно оси OY. Сколько различных треугольников можно получить за три таких шага, если начать с треугольника ABC, изображенного на рисунке?","options":[{"text":"9"},{"text":"10"},{"text":"15"},{"text":"27"},{"text":"другой ответ"}],"condition":{"src":"assets/grades-7-8/2002/task-25.svg","width":158,"height":137,"alt":"Оси OX и OY. Вершины треугольника имеют координаты A(2; 0), B(1; 1) и C(1; −1)."},"answer":1,"points":5,"review":[{"title":"Решение","text":"Исходный треугольник симметричен относительно OX. Поэтому для его положения достаточно знать, справа он от OY или слева и какова высота вершины A. Начальное положение — справа, высота 0."},{"title":"Решение","text":"Сдвиг прибавляет 1 к высоте, отражение в OX меняет её знак, а отражение в OY переносит фигуру на другую сторону."},{"title":"Ответ","text":"После двух шагов справа возможны высоты −1, 0, 1, 2, а слева — 0, 1. Применив ещё один шаг, получаем справа шесть высот от −2 до 3, слева четыре от −1 до 2. Всего 10 положений."}]},{"number":26,"title":"Слова Альберта","question":"Альберт всегда лжет. Однажды он сказал своему другу Франку: «Хотя бы один из нас никогда не лжет». Тогда обязательно","options":[{"text":"Франк всегда лжет"},{"text":"бывает, что Франк лжет"},{"text":"Франк никогда не лжет"},{"text":"бывает, что Франк говорит правду"},{"text":"Альберт не мог произнести такую фразу"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Альберт солгал. Значит, неверно, что хотя бы один из двоих никогда не лжёт."},{"title":"Ответ","text":"У каждого из них бывает хотя бы одна ложь. Поэтому Франк иногда лжёт."}]},{"number":27,"title":"Будильник","question":"В 12:00 будильник установили правильно, и он пошел, отставая на 1 минуту в час. Когда этот будильник показал 13:00, его завели, но после этого он почему-то стал спешить на 1 минуту в час. Какое время будет на самом деле в тот момент, когда этот будильник покажет 14:00?","options":[{"text":"14 час"},{"text":"14 час 120/3599 мин"},{"text":"14 час 1/59 мин"},{"text":"13 час 59 1/61 мин"},{"text":"невозможно определить"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"В первый период за 60 настоящих минут на будильнике проходит 59 минут. Поэтому его первый час занимает 3600/59 настоящих минут."},{"title":"Ответ","text":"Во второй период час на будильнике занимает 3600/61 настоящих минут. Вместе прошло 3600/59 + 3600/61 = 120 + 120/3599 минут после полудня."}]},{"number":28,"title":"Треугольники на точках","question":"На рисунке отмечены вершины и центр правильного шестиугольника. Назовем тройку отмеченных точек хорошей, если эти точки образуют равнобедренный треугольник. Сколько хороших троек на рисунке?","options":[{"text":"6"},{"text":"18"},{"text":"20"},{"text":"30"},{"text":"36"}],"condition":{"src":"assets/grades-7-8/2002/task-28.svg","width":107,"height":88,"alt":"Семь точек: шесть вершин правильного шестиугольника и точка в его центре."},"answer":2,"points":5,"review":[{"title":"Решение","text":"С центром и двумя вершинами получается 6 · 5 / 2 = 15 троек. Три пары противоположных вершин лежат на прямой с центром. Остаётся 12 равнобедренных треугольников."},{"title":"Ответ","text":"Без центра у каждой из шести вершин есть две симметричные пары других вершин. Это 12 подсчётов, но два равносторонних треугольника посчитаны по три раза. Получаем 12 − 4 = 8 треугольников без центра, всего 20."}]},{"number":29,"title":"Простые числа","question":"Сколько простых чисел равны сумме двух простых чисел и одновременно разности двух простых чисел?","options":[{"text":"1"},{"text":"3"},{"text":"4"},{"text":"0"},{"text":"бесконечно много"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Число 2 нельзя представить суммой простых чисел. Для нечётного простого p в каждом представлении одно из простых чисел должно быть чётным, то есть равным 2."},{"title":"Решение","text":"Тогда p − 2 и p + 2 должны быть простыми. Среди трёх чисел p − 2, p, p + 2 одно делится на 3. Оно должно равняться 3."},{"title":"Ответ","text":"Подходит только p = 5: число 3 нельзя представить нужной суммой, а p + 2 не может быть равно 3. Проверка: 5 = 3 + 2 = 7 − 2."}]},{"number":30,"title":"Сумма трёх дробей","question":"Известно, что a + b + c = 7 и 1/(a + b) + 1/(b + c) + 1/(a + c) = 7/10. Тогда число a/(b + c) + b/(a + c) + c/(a + b) равно","options":[{"text":"19/10"},{"text":"17/10"},{"text":"9/7"},{"text":"3/2"},{"text":"10/7"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Подставляем a = 7 − (b + c). Тогда a/(b + c) = 7/(b + c) − 1. Так же преобразуем две другие дроби."},{"title":"Ответ","text":"Сумма равна 7 · (7/10) − 3 = 19/10."}]}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2002-7-8"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2002] ?? []).find(edition => edition.id === "2002-7-8")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
